                "a": "Model completed story: The boys decided to go in. All five of them agreed, though Javed was a little afraid. They went in together, holding each other's hands. Inside, it was dark and cold. Suddenly they heard a strange sound, 'thud, thud', from the upper floor. They stayed inside for about ten minutes. Javed was so scared that he ran out after two minutes. Rashid was the bravest; he was not scared at all. When they finally came out, they saw Shahid standing outside, laughing. He told them that he had hidden in the house and made the strange sounds to frighten them. The boys laughed too and told everyone that there were no ghosts in the yellow house. It was only Shahid's trick.",
