                "q": "Exercise 7.1: How has social media revolutionized the concept of communication?",
                "a": "Social media has changed the concept of communication and community. Interactive websites and applications enable users to create and share information, videos and original thoughts. Community is no longer the immediate community in which we live; it has now expanded to include the entire world, and one has become a part of a global community."
