              {
                "a": "To give happiness, I will speak gently to everyone, smile when I meet people, and help my friends in their need. To avoid hurting people, I will never speak harshly or shout at anyone, and I will never make fun of others. For example, I will greet my teachers politely every day, and I will not use bad words even when I am angry.",
                "q": "Exercise 8. State one thing you will do to give happiness and one thing you will do to avoid hurting people."
              }
