            "items": [
              {
                "a": "Model speech: The most important thing I own is a wristwatch. I got it from my father. I have had it for two years. My father gave it to me on my birthday. He bought it from a shop in Hyderabad. He bought it because he wanted me to learn the value of time. It is important to me because it reminds me of my father's love and teaches me to be punctual. I wear it every day and I take great care of it.",
                "q": "Exercise 1. Describe something that you own which is very important to you. (Where did you get it from? How long have you had it? Who gave it to you? When did you purchase it? Why did you purchase it? Why is it important to you?)"
              },
              {
                "a": "Model speech: Good morning, everyone. Today I will speak about the importance of a clean environment. A clean environment is necessary for our health and happiness. First, a clean environment keeps us healthy. Dirty streets and polluted water spread diseases like malaria, dengue, and cholera. Second, a clean environment looks beautiful. Green trees, clean parks, and tidy streets make our town a pleasant place to live in. Third, a clean environment is our duty. We should not throw rubbish in the streets. We should plant trees and keep our homes, schools, and streets clean. In conclusion, a clean environment means a healthy life. Let us all work together to keep our environment clean. Thank you.",
                "q": "Exercise 2. Prepare a three-minute speech about the importance of a clean environment."
              }
            ],
