              {
                "q": "Exercise 1. Work in pairs and practise the following dialogue. First one of you takes the role of the client and the other that of the travel agent. Then, reverse roles and practise again.",
                "a": "Travel Agent: How was your trip? Client: It was a disaster. You charged me a high price and provided low services. Travel Agent: Sir, you, yourself, chose the package and the facilities. Client: Yes, I did, but the package stated one thing and provided something else. I'm here to get my money back. Travel Agent: Please accept my apologies for any inconvenience. Client: I am not here for apologies. I want my money back. Travel Agent: Let me see how I can help you. Client: You did not even provide a good resort as mentioned in the prime package. Travel Agent: Well, the company can return you half of the price that you paid. How about that? Client: This sounds great to me. Thank you."
              },
              {
                "q": "Exercise 2. Situation: You are siblings. Your parents have given you some money to buy a dress, a bag, and a pair of footwear. You need to agree on how much money to spend on each item and why. Work in pairs and come to a consensus. You can use some of the phrases given in the box above.",
                "a": "Model dialogue: A: Let's discuss this. We have money for a dress, a bag and a pair of footwear. I think we should spend the most on the dress because it is the most important item. B: I agree with you, but the bag should also be of good quality because we will use it every day. A: In my opinion, we can buy a simple dress and a good bag. What do you think about the footwear? B: This sounds good. Let's buy comfortable footwear, because cheap shoes hurt the feet. A: Let's see. We can spend half the money on the dress, and divide the rest equally between the bag and the footwear. B: I like this idea. We can sort this out easily. Let's go shopping tomorrow."
              },
              {
                "q": "Exercise 3. Situation: The Principal has given your class permission to go for an outing/trip. Some of the students want to go to the beach, some to Makli, others to the Hub dam, while others want to go to Ranikot. Work in groups of four and come to a consensus. You can use some of the phrases given in the box above.",
                "a": "Model dialogue: A: In my opinion, we should go to the beach because it is near and everyone enjoys the sea. B: I have a different idea. Makli is a historical place, and we can learn a lot there. C: I don't think Makli is a good choice for a picnic. Let's discuss this. The Hub Dam is also a beautiful place. D: I agree with you. The Hub Dam has water, greenery and fresh air. Ranikot is too far for one day. A: Let's see. The beach is the best choice because it is close, safe and fun for everyone. B: This sounds good. We can sort this out. Let's agree on the beach and tell the teacher."
              }
