            "name": "Writing",
            "items": [
              {
                "q": "Exercise 1.1. Identify the appeal to persuasion in: 'Thousands of poor little children suffer a harsh, painful death every day without food or aid due to political instability.'",
                "a": "Emotion — it appeals to the reader's feelings of pity and sympathy for poor children."
              },
              {
                "q": "Exercise 1.2. Identify the appeal to persuasion in: 'A 45% decrease in the mortality rate has been witnessed after the vaccination drive against Corona Virus.'",
                "a": "Logic — it uses facts and figures (45% decrease) to persuade the reader intellectually."
              },
              {
                "q": "Exercise 1.3. Identify the appeal to persuasion in: 'As a doctor, I can tell you that this course of treatment will likely generate the best results.'",
                "a": "Ethics and Credibility — the writer is a doctor, an expert, so the reader can trust him."
              },
              {
                "q": "Exercise 1.4. Identify the appeal to persuasion in: 'If we don't move soon, we're all going to die! Can't you see how dangerous it would be to stay?'",
                "a": "Emotion — it appeals to the reader's fear."
              },
              {
                "q": "Exercise 1.5. Identify the appeal to persuasion in: 'I have written a lot on this topic and presented my work at a number of international conferences.'",
                "a": "Ethics and Credibility — the writer's experience and work make him trustworthy."
              },
              {
                "q": "Exercise 1.6. Identify the appeal to persuasion in: 'Many people are lying under the open sky since the earthquake two weeks ago hoping that someone would help them.'",
                "a": "Emotion — it appeals to the reader's sympathy for earthquake victims."
              },
              {
                "q": "Exercise 1.7. Identify the appeal to persuasion in: 'This claim has been verified by research in 75 countries, over a period of seven years.'",
                "a": "Logic — it uses research and facts to persuade the reader."
              },
              {
                "q": "Exercise 1.8. Identify the appeal to persuasion in: 'The writer of this article is a world renowned pharmacist, who has been working this field for over twenty years.'",
                "a": "Ethics and Credibility — the writer is a world renowned expert, so he can be trusted."
              },
              {
                "q": "Exercise 2. Write a persuasive essay on one of the following topics: 1. Girls should be educated 2. Sports and games should be made compulsory for all students 3. Students should be encouraged to speak in English in the School 4. Students should be guided and supported to grow some vegetables at home 5. Knowledge about diseases and vaccinations should be made a part of the Curriculum",
                "a": "Model essay — Girls should be educated. Paragraph 1 (Introduction): Education is the basic right of every child, whether a boy or a girl. Yet, in many parts of our country, girls are still kept away from schools. I strongly believe that girls should be educated, because an educated girl can change her family, her society and her country. Paragraph 2 (Support 1): Firstly, an educated girl becomes a good mother and a good citizen. She can look after the health and education of her children and guide them in the right direction. According to a survey, children of educated mothers are healthier and perform better at school. Paragraph 3 (Support 2): Secondly, girls' education helps the country to progress. When girls are educated, they become teachers, doctors, engineers and leaders. They earn money and support their families, which reduces poverty. Paragraph 4 (Opposite viewpoint): Some people say that girls do not need education because they will only work at home. However, this is wrong. Even at home, an educated girl manages the house better, teaches her children and keeps her family healthy. Education is useful everywhere. Paragraph 5 (Conclusion): In conclusion, girls should be educated because education makes them strong, useful and confident. The government and parents should work together so that no girl is left without education."
              }
            ]
