          "Matter is anything that has mass and occupies space.",
          "The three states of matter are solid, liquid and gas.",
          "An element is a pure substance made of only one kind of atom.",
          "A compound is made of two or more elements joined in a fixed ratio.",
          "A mixture is made of two or more substances mixed together without a fixed ratio.",
          "A physical change does not make a new substance, for example melting of ice.",
          "A chemical change makes a new substance, for example burning of wood.",
          "The symbol of an element is one or two letters, for example H, O, Na, Ca.",
          "A chemical formula shows the atoms in a compound, for example H2O for water."
