          "An atom has three main particles: protons, neutrons and electrons.",
          "Protons are positively charged and are found in the nucleus.",
          "Neutrons have no charge and are found in the nucleus.",
          "Electrons are negatively charged and move around the nucleus in shells.",
          "The atomic number (Z) is the number of protons in an atom.",
          "The mass number (A) is the total number of protons and neutrons.",
          "Isotopes are atoms of the same element with the same atomic number but different mass numbers.",
          "Electrons are arranged in shells K, L, M, N; the K shell holds 2 electrons and the L shell holds 8.",
          "The number of electrons in a neutral atom is equal to the number of protons."
