          "The horizontal rows are called periods; there are 7 periods.",
          "The vertical columns are called groups; there are 18 groups.",
          "Elements in the same group have the same number of electrons in their outer shell.",
          "Group 1 elements are called alkali metals, for example lithium, sodium and potassium.",
          "Group 17 elements are called halogens, for example fluorine, chlorine and bromine.",
          "Group 18 elements are called noble gases, for example helium, neon and argon.",
          "Metals are found on the left side of the periodic table; non-metals are on the right.",
